using Microsoft.Data.SqlClient;using System.Data;
namespace ProjectTasks.DAL;
public sealed class TaskRepository
{
 public DataTable Projects(){using var c=Db.Open();using var d=new SqlDataAdapter("SELECT MaDuAn,TenDuAn,NgayBatDau,NgayKetThuc,TrangThai FROM DuAn ORDER BY MaDuAn",c);var t=new DataTable();d.Fill(t);return t;}
 public DataTable Members(){using var c=Db.Open();using var d=new SqlDataAdapter("SELECT MaThanhVien,HoTen,Email,ChuyenMon FROM ThanhVien ORDER BY HoTen",c);var t=new DataTable();d.Fill(t);return t;}
 public DataTable Tasks(int project,string status="Tất cả"){using var c=Db.Open();using var d=new SqlDataAdapter("SELECT t.MaTask,t.MaDuAn,p.TenDuAn,t.TenTask,t.MoTa,t.HanNop,t.DoUuTien,t.TrangThai,STRING_AGG(m.HoTen,N', ') AS NguoiPhuTrach FROM CongViec t JOIN DuAn p ON p.MaDuAn=t.MaDuAn LEFT JOIN PhanCong a ON a.MaTask=t.MaTask LEFT JOIN ThanhVien m ON m.MaThanhVien=a.MaThanhVien WHERE (@p=0 OR t.MaDuAn=@p) AND (@s=N'Tất cả' OR t.TrangThai=@s) GROUP BY t.MaTask,t.MaDuAn,p.TenDuAn,t.TenTask,t.MoTa,t.HanNop,t.DoUuTien,t.TrangThai ORDER BY t.HanNop,t.MaTask",c);d.SelectCommand!.Parameters.Add("@p",SqlDbType.Int).Value=project;d.SelectCommand.Parameters.Add("@s",SqlDbType.NVarChar,50).Value=status;var t=new DataTable();d.Fill(t);return t;}
 public void SaveProject(int? id,string name,DateTime? start,DateTime? end,string status){using var c=Db.Open();using var x=new SqlCommand(id is null?"INSERT DuAn(TenDuAn,NgayBatDau,NgayKetThuc,TrangThai) VALUES(@n,@b,@e,@s)":"UPDATE DuAn SET TenDuAn=@n,NgayBatDau=@b,NgayKetThuc=@e,TrangThai=@s WHERE MaDuAn=@id",c);x.Parameters.Add("@n",SqlDbType.NVarChar,150).Value=name;x.Parameters.Add("@b",SqlDbType.DateTime).Value=(object?)start??DBNull.Value;x.Parameters.Add("@e",SqlDbType.DateTime).Value=(object?)end??DBNull.Value;x.Parameters.Add("@s",SqlDbType.NVarChar,50).Value=status;if(id!=null)x.Parameters.Add("@id",SqlDbType.Int).Value=id;x.ExecuteNonQuery();}
 public void DeleteProject(int id){using var c=Db.Open();using var tr=c.BeginTransaction();try{using var x=new SqlCommand("DELETE FROM PhanCong WHERE MaTask IN(SELECT MaTask FROM CongViec WHERE MaDuAn=@id); DELETE FROM CongViec WHERE MaDuAn=@id; DELETE FROM DuAn WHERE MaDuAn=@id",c,tr);x.Parameters.Add("@id",SqlDbType.Int).Value=id;x.ExecuteNonQuery();tr.Commit();}catch{tr.Rollback();throw;}}
 public int SaveTask(int? id,int project,string name,string description,DateTime? due,string priority,string status,IEnumerable<int> members){using var c=Db.Open();using var tr=c.BeginTransaction();try{int task;if(id is null){using var x=new SqlCommand("INSERT CongViec(MaDuAn,TenTask,MoTa,HanNop,DoUuTien,TrangThai); SELECT CAST(SCOPE_IDENTITY() AS int)",c,tr);AddTaskParams(x,project,name,description,due,priority,status);task=(int)x.ExecuteScalar()!;}else{task=id.Value;using var x=new SqlCommand("UPDATE CongViec SET MaDuAn=@p,TenTask=@n,MoTa=@d,HanNop=@due,DoUuTien=@priority,TrangThai=@status WHERE MaTask=@id",c,tr);AddTaskParams(x,project,name,description,due,priority,status);x.Parameters.Add("@id",SqlDbType.Int).Value=task;x.ExecuteNonQuery();}using(var del=new SqlCommand("DELETE FROM PhanCong WHERE MaTask=@id",c,tr)){del.Parameters.Add("@id",SqlDbType.Int).Value=task;del.ExecuteNonQuery();}foreach(int m in members.Distinct()){using var a=new SqlCommand("INSERT PhanCong(MaTask,MaThanhVien) VALUES(@t,@m)",c,tr);a.Parameters.Add("@t",SqlDbType.Int).Value=task;a.Parameters.Add("@m",SqlDbType.Int).Value=m;a.ExecuteNonQuery();}tr.Commit();return task;}catch{tr.Rollback();throw;}}
 static void AddTaskParams(SqlCommand x,int project,string name,string description,DateTime? due,string priority,string status){x.Parameters.Add("@p",SqlDbType.Int).Value=project;x.Parameters.Add("@n",SqlDbType.NVarChar,200).Value=name;x.Parameters.Add("@d",SqlDbType.NVarChar,-1).Value=description;x.Parameters.Add("@due",SqlDbType.DateTime).Value=(object?)due??DBNull.Value;x.Parameters.Add("@priority",SqlDbType.NVarChar,20).Value=priority;x.Parameters.Add("@status",SqlDbType.NVarChar,50).Value=status;}
 public void DeleteTask(int id){using var c=Db.Open();using var x=new SqlCommand("DELETE CongViec WHERE MaTask=@id",c);x.Parameters.Add("@id",SqlDbType.Int).Value=id;x.ExecuteNonQuery();}
 public void SetStatus(int id,string status){using var c=Db.Open();using var x=new SqlCommand("UPDATE CongViec SET TrangThai=@s WHERE MaTask=@id",c);x.Parameters.Add("@s",SqlDbType.NVarChar,50).Value=status;x.Parameters.Add("@id",SqlDbType.Int).Value=id;x.ExecuteNonQuery();}
 public int[] AssignedMembers(int task){using var c=Db.Open();using var x=new SqlCommand("SELECT MaThanhVien FROM PhanCong WHERE MaTask=@id",c);x.Parameters.Add("@id",SqlDbType.Int).Value=task;using var r=x.ExecuteReader();var a=new List<int>();while(r.Read())a.Add(r.GetInt32(0));return a.ToArray();}
 public DataTable Overdue(){using var c=Db.Open();using var x=new SqlCommand("SELECT t.MaTask,p.TenDuAn,t.TenTask,t.HanNop,t.DoUuTien,t.TrangThai FROM CongViec t JOIN DuAn p ON p.MaDuAn=t.MaDuAn WHERE t.HanNop<GETDATE() AND t.TrangThai<>N'Done' ORDER BY t.HanNop",c);using var r=x.ExecuteReader();var t=new DataTable();t.Load(r);return t;}
 public DataTable Completion(){using var c=Db.Open();using var d=new SqlDataAdapter("SELECT p.TenDuAn,m.HoTen,COUNT(t.MaTask) AS TongViec,SUM(CASE WHEN t.TrangThai=N'Done' THEN 1 ELSE 0 END) AS DaHoanThanh,CAST(100.0*SUM(CASE WHEN t.TrangThai=N'Done' THEN 1 ELSE 0 END)/NULLIF(COUNT(t.MaTask),0) AS DECIMAL(5,1)) AS TyLePhanTram FROM ThanhVien m LEFT JOIN PhanCong a ON a.MaThanhVien=m.MaThanhVien LEFT JOIN CongViec t ON t.MaTask=a.MaTask LEFT JOIN DuAn p ON p.MaDuAn=t.MaDuAn GROUP BY p.TenDuAn,m.HoTen ORDER BY p.TenDuAn,m.HoTen",c);var t=new DataTable();d.Fill(t);return t;}
 public int Scalar(string sql){using var c=Db.Open();using var x=new SqlCommand(sql,c);return Convert.ToInt32(x.ExecuteScalar()??0);}
}